// JAH demo program — Comprehension check
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function comprehends(heard, inferred){ if(!heard) return 'not heard — ask repeat';
  if(!inferred) return 'heard, not understood — paraphrase'; return 'understood'; }
check("heard + inferred", comprehends(true,true), "understood");
check("heard only", comprehends(true,false), "heard, not understood \u2014 paraphrase");
check("missed it", comprehends(false,false), "not heard \u2014 ask repeat");
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

